/// Declarative Brickfall layouts.
///
/// Each layout is a list of rows, exactly [kBrickCols] characters wide, read
/// top to bottom. Legend:
///
/// * `.` empty
/// * `1` normal brick (1 hit)
/// * `2` / `3` tough brick (2 or 3 hits)
/// * `#` steel brick (indestructible)
/// * `*` explosive brick (clears its 8 neighbours)
/// * `W` `M` `S` `L` `H` normal brick that always drops a capsule:
///   Wide paddle, Multi-ball, Slow ball, Laser, Heart (extra life)
///
/// Levels 1..[kAuthoredLevels.length] are authored here; later levels are
/// generated by `BrickWorld.generateLayout`.
library;

const int kBrickCols = 10;
const int kBrickMaxRows = 14;

class BrickLevelDef {
  const BrickLevelDef(this.name, this.rows);
  final String name;
  final List<String> rows;
}

